import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { supabase } from '../servicios/supabase';
import { obtenerSucursal, obtenerEstrellas, obtenerFeedbacks, agregarFeedback, EMOJIS_MOOD, obtenerEtiquetasPorMood } from '../data/mockDiscoveryDB';
import { useAuth } from '../contextos/AuthContext';
import TarjetaViaje from '../componentes/TarjetaViaje';
import PanelFiltros from '../componentes/PanelFiltros';
import '../estilos/escritorio/buscador.css';
import '../estilos/escritorio/filtros.css';
import '../estilos/movil/buscador-responsivo.css';
import '../estilos/movil/filtros-responsivo.css';

/**
 * SucursalDetalle — V4: Branch detail with paginated trips and emoji feedback system.
 */
const SucursalDetalle = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const { sesion, perfil } = useAuth();

    // Branch info
    const [sucursal, setSucursal] = useState(null);
    const [cargandoSucursal, setCargandoSucursal] = useState(true);

    // Trips and filtering
    const [viajes, setViajes] = useState([]);
    const [cargandoViajes, setCargandoViajes] = useState(false);
    const [buscado, setBuscado] = useState(false);

    // Pagination
    const VIAJES_POR_PAGINA = 4;
    const [paginaActual, setPaginaActual] = useState(1);

    // Advanced filters
    const [filtrosAvanzados, setFiltrosAvanzados] = useState({
        precioMin: '',
        precioMax: '',
        calidadMinima: 0,
        amenidades: [],
    });

    // Feedback state
    const [feedbacks, setFeedbacks] = useState([]);
    const [mood, setMood] = useState(0);
    const [etiquetasSeleccionadas, setEtiquetasSeleccionadas] = useState([]);
    const [comentario, setComentario] = useState('');
    const [feedbackEnviado, setFeedbackEnviado] = useState(false);

    useEffect(() => {
        cargarSucursal();
    }, [id]);

    const cargarSucursal = async () => {
        setCargandoSucursal(true);

        // Try mockDiscoveryDB first
        const sucursalLocal = obtenerSucursal(id);
        if (sucursalLocal) {
            setSucursal(sucursalLocal);
            setCargandoSucursal(false);
            cargarViajesDemo();
            setFeedbacks(obtenerFeedbacks(id));
            return;
        }

        // Fallback to Supabase
        try {
            const { data, error } = await supabase
                .from('sucursales')
                .select('*')
                .eq('id', id)
                .single();

            if (error) {
                setSucursal({ id, nombre: 'Sucursal no encontrada', ranking: 0 });
            } else {
                setSucursal(data);
                cargarViajesSucursal(data.id);
            }
        } catch (err) {
            setSucursal({ id, nombre: 'Sin conexión', ranking: 0 });
        } finally {
            setCargandoSucursal(false);
        }
    };

    const cargarViajesSucursal = async (sucursalId) => {
        setCargandoViajes(true);
        setBuscado(true);
        try {
            let query = supabase
                .from('viajes')
                .select(`id, origen, destino, salida, precio, duracion_estimada, estado,
                    buses!inner ( id, capacidad, sucursal_id, sucursales!inner ( id, nombre, ranking, amenidades ) )`)
                .eq('buses.sucursal_id', sucursalId || id)
                .eq('estado', 'programado')
                .order('salida', { ascending: true });

            if (filtrosAvanzados.precioMin !== '') query = query.gte('precio', parseFloat(filtrosAvanzados.precioMin));
            if (filtrosAvanzados.precioMax !== '') query = query.lte('precio', parseFloat(filtrosAvanzados.precioMax));

            const { data, error } = await query;
            if (error) { cargarViajesDemo(); return; }

            if (data && data.length > 0) {
                let resultado = data.map(v => ({
                    id: v.id, sucursal_nombre: v.buses.sucursales.nombre,
                    ranking: v.buses.sucursales.ranking, origen: v.origen,
                    destino: v.destino, salida: v.salida, precio: v.precio,
                    duracion_estimada: v.duracion_estimada,
                    amenidades: v.buses.sucursales.amenidades || [],
                }));
                if (filtrosAvanzados.calidadMinima > 0)
                    resultado = resultado.filter(v => v.ranking >= filtrosAvanzados.calidadMinima);
                if (filtrosAvanzados.amenidades.length > 0)
                    resultado = resultado.filter(v => filtrosAvanzados.amenidades.every(a => v.amenidades.includes(a)));
                setViajes(resultado);
            } else {
                setViajes([]);
            }
        } catch { cargarViajesDemo(); }
        finally { setCargandoViajes(false); }
    };

    const cargarViajesDemo = () => {
        let viajesDemo = [
            { id: 'demo-v1', sucursal_nombre: sucursal?.nombre || 'Sucursal', ranking: sucursal?.ranking || 4.0, origen: 'La Paz', destino: 'Cochabamba', salida: '2026-04-02T08:00:00', precio: 45, duracion_estimada: '7h 30min', amenidades: [] },
            { id: 'demo-v2', sucursal_nombre: sucursal?.nombre || 'Sucursal', ranking: sucursal?.ranking || 4.0, origen: 'La Paz', destino: 'Santa Cruz', salida: '2026-04-02T20:00:00', precio: 85, duracion_estimada: '12h', amenidades: [] },
            { id: 'demo-v3', sucursal_nombre: sucursal?.nombre || 'Sucursal', ranking: sucursal?.ranking || 4.0, origen: 'Cochabamba', destino: 'Sucre', salida: '2026-04-03T06:30:00', precio: 35, duracion_estimada: '5h', amenidades: [] },
            { id: 'demo-v4', sucursal_nombre: sucursal?.nombre || 'Sucursal', ranking: sucursal?.ranking || 4.0, origen: 'La Paz', destino: 'Oruro', salida: '2026-04-03T10:00:00', precio: 25, duracion_estimada: '3h 30min', amenidades: [] },
            { id: 'demo-v5', sucursal_nombre: sucursal?.nombre || 'Sucursal', ranking: sucursal?.ranking || 4.0, origen: 'La Paz', destino: 'Potosí', salida: '2026-04-03T22:00:00', precio: 65, duracion_estimada: '10h', amenidades: [] },
            { id: 'demo-v6', sucursal_nombre: sucursal?.nombre || 'Sucursal', ranking: sucursal?.ranking || 4.0, origen: 'Santa Cruz', destino: 'Tarija', salida: '2026-04-04T07:00:00', precio: 95, duracion_estimada: '14h', amenidades: [] },
            { id: 'demo-v7', sucursal_nombre: sucursal?.nombre || 'Sucursal', ranking: sucursal?.ranking || 4.0, origen: 'Cochabamba', destino: 'Trinidad', salida: '2026-04-04T18:00:00', precio: 110, duracion_estimada: '16h', amenidades: [] },
        ];

        if (filtrosAvanzados.precioMin !== '') viajesDemo = viajesDemo.filter(v => v.precio >= parseFloat(filtrosAvanzados.precioMin));
        if (filtrosAvanzados.precioMax !== '') viajesDemo = viajesDemo.filter(v => v.precio <= parseFloat(filtrosAvanzados.precioMax));

        setViajes(viajesDemo);
        setCargandoViajes(false);
        setBuscado(true);
    };

    const aplicarFiltros = () => {
        setPaginaActual(1);
        if (sucursal && obtenerSucursal(id)) {
            cargarViajesDemo();
        } else if (sucursal) {
            cargarViajesSucursal(sucursal.id);
        }
    };

    const handleSeleccionar = (viaje) => {
        navigate('/reserva/' + viaje.id);
    };

    // ── Pagination Logic ──────────────────────────────
    const totalPaginas = Math.ceil(viajes.length / VIAJES_POR_PAGINA);
    const viajesPaginados = viajes.slice(
        (paginaActual - 1) * VIAJES_POR_PAGINA,
        paginaActual * VIAJES_POR_PAGINA
    );

    // ── Feedback Handlers ─────────────────────────────
    const toggleEtiqueta = (etiqueta) => {
        setEtiquetasSeleccionadas(prev =>
            prev.includes(etiqueta) ? prev.filter(e => e !== etiqueta) : [...prev, etiqueta]
        );
    };

    const handleEnviarFeedback = () => {
        if (mood === 0) return;
        const nombreUsuario = perfil?.nombreCompleto || perfil?.nombre_completo || perfil?.email || sesion?.user?.nombreCompleto || 'Viajero Anónimo';
        agregarFeedback(id, {
            mood,
            etiquetas: etiquetasSeleccionadas,
            comentario,
            nombreUsuario,
        });
        setFeedbacks(obtenerFeedbacks(id));
        setMood(0);
        setEtiquetasSeleccionadas([]);
        setComentario('');
        setFeedbackEnviado(true);
        setTimeout(() => setFeedbackEnviado(false), 3000);
    };

    // ── Star rendering ────────────────────────────────
    const renderEstrellas = (rating) => {
        const estrellas = obtenerEstrellas(rating || 0);
        return (
            <div style={{ display: 'flex', gap: '2px', alignItems: 'center' }}>
                {estrellas.map((tipo, i) => (
                    <span key={i} style={{ fontSize: '1rem', color: tipo === 'empty' ? '#334155' : '#f59e0b', opacity: tipo === 'half' ? 0.6 : 1 }}>★</span>
                ))}
                <span style={{ color: '#94a3b8', fontSize: '0.85rem', marginLeft: '0.3rem' }}>({rating})</span>
            </div>
        );
    };

    if (cargandoSucursal) {
        return (
            <div className="contenedor-buscador">
                <div className="estado-carga"><div className="spinner"></div><p>Cargando información...</p></div>
            </div>
        );
    }

    return (
        <div className="contenedor-buscador">

            {/* ═══════ HEADER ═══════ */}
            <div className="buscador-header">
                <button className="btn-volver" onClick={() => navigate(-1)} id="btn-volver-sucursal">← Volver</button>
                <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', flexWrap: 'wrap' }}>
                    {sucursal?.logo && (
                        <div style={{
                            width: '48px', height: '48px', borderRadius: '12px',
                            background: `${sucursal.colorLogo || '#3b82f6'}20`, border: `1px solid ${sucursal.colorLogo || '#3b82f6'}40`,
                            display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.5rem',
                        }}>{sucursal.logo}</div>
                    )}
                    <div>
                        <h1 style={{ margin: 0 }}>{sucursal?.nombre || 'Sucursal'}</h1>
                        {sucursal && renderEstrellas(sucursal.ranking)}
                    </div>
                </div>
            </div>

            {/* ═══════ FILTERS ═══════ */}
            <PanelFiltros
                filtros={filtrosAvanzados}
                onFiltrosChange={setFiltrosAvanzados}
                modoSucursal={true}
                onBuscar={aplicarFiltros}
            />

            {/* ═══════ TRIP RESULTS (PAGINATED) ═══════ */}
            <div className="buscador-resultados" id="resultados-sucursal">
                {cargandoViajes && (
                    <div className="estado-carga"><div className="spinner"></div><p>Cargando viajes...</p></div>
                )}

                {!cargandoViajes && buscado && viajes.length === 0 && (
                    <div className="estado-vacio">
                        <span className="icono-vacio">🚌</span>
                        <h3>No hay viajes disponibles</h3>
                        <p>No hay viajes con los filtros seleccionados</p>
                    </div>
                )}

                {!cargandoViajes && viajes.length > 0 && (
                    <>
                        <div className="resultados-info" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap' }}>
                            <p>{viajes.length} viaje{viajes.length !== 1 ? 's' : ''} de {sucursal?.nombre}</p>
                            <span style={{ color: '#64748b', fontSize: '0.85rem' }}>Página {paginaActual} de {totalPaginas}</span>
                        </div>

                        <div className="lista-viajes">
                            {viajesPaginados.map(viaje => (
                                <TarjetaViaje key={viaje.id} viaje={viaje} onSeleccionar={handleSeleccionar} />
                            ))}
                        </div>

                        {/* Pagination Controls */}
                        {totalPaginas > 1 && (
                            <div style={{
                                display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '0.75rem',
                                marginTop: '1.5rem', padding: '1rem',
                            }}>
                                <button
                                    onClick={() => setPaginaActual(p => Math.max(1, p - 1))}
                                    disabled={paginaActual === 1}
                                    style={{
                                        padding: '0.6rem 1.2rem', borderRadius: '8px', border: 'none',
                                        background: paginaActual === 1 ? '#1e293b' : '#334155',
                                        color: paginaActual === 1 ? '#475569' : '#f1f5f9',
                                        cursor: paginaActual === 1 ? 'not-allowed' : 'pointer', fontWeight: 500,
                                    }}
                                >← Anterior</button>

                                {Array.from({ length: totalPaginas }, (_, i) => i + 1).map(num => (
                                    <button key={num} onClick={() => setPaginaActual(num)}
                                        style={{
                                            width: '36px', height: '36px', borderRadius: '8px', border: 'none',
                                            background: paginaActual === num ? '#3b82f6' : '#1e293b',
                                            color: paginaActual === num ? 'white' : '#94a3b8',
                                            fontWeight: 600, cursor: 'pointer', fontSize: '0.9rem',
                                        }}
                                    >{num}</button>
                                ))}

                                <button
                                    onClick={() => setPaginaActual(p => Math.min(totalPaginas, p + 1))}
                                    disabled={paginaActual === totalPaginas}
                                    style={{
                                        padding: '0.6rem 1.2rem', borderRadius: '8px', border: 'none',
                                        background: paginaActual === totalPaginas ? '#1e293b' : '#334155',
                                        color: paginaActual === totalPaginas ? '#475569' : '#f1f5f9',
                                        cursor: paginaActual === totalPaginas ? 'not-allowed' : 'pointer', fontWeight: 500,
                                    }}
                                >Siguiente →</button>
                            </div>
                        )}
                    </>
                )}
            </div>

            {/* ═══════ FEEDBACK SECTION ═══════ */}
            <div style={{
                marginTop: '2rem', background: '#1e293b', borderRadius: '14px',
                border: '1px solid #334155', padding: '1.5rem', maxWidth: '100%',
            }}>
                <h2 style={{ fontSize: '1.15rem', marginTop: 0, marginBottom: '0.5rem', color: '#f1f5f9' }}>
                    💬 Experiencias de Usuarios
                </h2>
                <p style={{ color: '#64748b', fontSize: '0.85rem', marginBottom: '1.5rem' }}>
                    ¿Cómo fue tu experiencia con {sucursal?.nombre}?
                </p>

                {/* Toast */}
                {feedbackEnviado && (
                    <div style={{
                        background: '#065f46', color: '#6ee7b7', padding: '0.75rem', borderRadius: '8px',
                        border: '1px solid #10b981', marginBottom: '1rem', fontSize: '0.9rem',
                    }}>
                        ✅ ¡Gracias por tu opinión!
                    </div>
                )}

                {/* Emoji Selector */}
                <div style={{ display: 'flex', justifyContent: 'center', gap: '0.5rem', marginBottom: '1rem' }}>
                    {EMOJIS_MOOD.map(e => (
                        <button key={e.valor} onClick={() => { setMood(e.valor); setEtiquetasSeleccionadas([]); }}
                            style={{
                                width: '52px', height: '52px', borderRadius: '12px', border: 'none',
                                background: mood === e.valor ? '#3b82f620' : '#0f172a',
                                outline: mood === e.valor ? '2px solid #3b82f6' : '1px solid #334155',
                                fontSize: '1.6rem', cursor: 'pointer',
                                transition: 'all 0.2s', transform: mood === e.valor ? 'scale(1.15)' : 'scale(1)',
                            }}
                            title={e.label}
                        >
                            {e.emoji}
                        </button>
                    ))}
                </div>

                {/* Mood label */}
                {mood > 0 && (
                    <div style={{ textAlign: 'center', marginBottom: '1rem', color: '#94a3b8', fontSize: '0.85rem', fontWeight: 500 }}>
                        {EMOJIS_MOOD.find(e => e.valor === mood)?.label}
                    </div>
                )}

                {/* Dynamic Labels */}
                {mood > 0 && (
                    <div style={{ marginBottom: '1.25rem' }}>
                        <div style={{ fontSize: '0.85rem', color: '#94a3b8', marginBottom: '0.5rem', fontWeight: 500 }}>
                            {mood < 3 ? 'Puntos a mejorar:' : mood === 3 ? 'Tu opinión:' : 'Puntos fuertes:'}
                        </div>
                        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                            {obtenerEtiquetasPorMood(mood).map(et => (
                                <button key={et} onClick={() => toggleEtiqueta(et)}
                                    style={{
                                        padding: '0.4rem 0.8rem', borderRadius: '999px', border: 'none',
                                        background: etiquetasSeleccionadas.includes(et) ? '#3b82f630' : '#0f172a',
                                        color: etiquetasSeleccionadas.includes(et) ? '#60a5fa' : '#94a3b8',
                                        outline: etiquetasSeleccionadas.includes(et) ? '1px solid #3b82f6' : '1px solid #334155',
                                        cursor: 'pointer', fontSize: '0.8rem', fontWeight: 500,
                                        transition: 'all 0.15s',
                                    }}
                                >{et}</button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Comment + Submit */}
                {mood > 0 && (
                    <div>
                        <textarea value={comentario} onChange={e => setComentario(e.target.value)}
                            placeholder="Escribe tu comentario (opcional)..."
                            rows={3}
                            style={{
                                width: '100%', boxSizing: 'border-box', background: '#0f172a',
                                border: '1px solid #334155', color: '#f1f5f9', padding: '0.8rem',
                                borderRadius: '10px', resize: 'vertical', fontSize: '0.9rem',
                                marginBottom: '0.75rem',
                            }}
                        />
                        <button onClick={handleEnviarFeedback}
                            style={{
                                width: '100%', padding: '0.8rem', borderRadius: '10px', border: 'none',
                                background: 'linear-gradient(135deg, #3b82f6, #2563eb)', color: 'white',
                                fontWeight: 600, cursor: 'pointer', fontSize: '0.9rem',
                            }}
                        >Enviar mi opinión</button>
                    </div>
                )}

                {/* Previous feedbacks */}
                {feedbacks.length > 0 && (
                    <div style={{ marginTop: '1.5rem', borderTop: '1px solid #334155', paddingTop: '1.25rem' }}>
                        <h3 style={{ fontSize: '0.95rem', color: '#94a3b8', marginTop: 0, marginBottom: '1rem' }}>
                            Opiniones recientes ({feedbacks.length})
                        </h3>
                        {feedbacks.slice(0, 5).map(fb => (
                            <div key={fb.id} style={{
                                background: '#0f172a', borderRadius: '10px', padding: '1rem',
                                border: '1px solid #1e293b', marginBottom: '0.75rem',
                            }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                        <span style={{ fontSize: '1.3rem' }}>{fb.avatar}</span>
                                        <span style={{ fontWeight: 600, color: '#f1f5f9', fontSize: '0.9rem' }}>{fb.nombreUsuario}</span>
                                    </div>
                                    <span style={{ fontSize: '1.3rem' }}>{EMOJIS_MOOD.find(e => e.valor === fb.mood)?.emoji}</span>
                                </div>
                                {fb.etiquetas && fb.etiquetas.length > 0 && (
                                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.3rem', marginBottom: '0.5rem' }}>
                                        {fb.etiquetas.map((et, i) => (
                                            <span key={i} style={{
                                                padding: '0.2rem 0.6rem', borderRadius: '999px', fontSize: '0.7rem',
                                                background: fb.mood >= 4 ? '#065f4620' : '#7f1d1d20',
                                                color: fb.mood >= 4 ? '#6ee7b7' : '#fca5a5',
                                                border: `1px solid ${fb.mood >= 4 ? '#10b98130' : '#ef444430'}`,
                                            }}>{et}</span>
                                        ))}
                                    </div>
                                )}
                                {fb.comentario && (
                                    <p style={{ color: '#cbd5e1', fontSize: '0.85rem', margin: 0, fontStyle: 'italic' }}>
                                        "{fb.comentario}"
                                    </p>
                                )}
                                <span style={{ color: '#475569', fontSize: '0.7rem', marginTop: '0.4rem', display: 'block' }}>
                                    {new Date(fb.fecha).toLocaleDateString('es-BO')}
                                </span>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
};

export default SucursalDetalle;
